package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;
/** Android WebView integration: replay recorded provider response and partial-batch recovery. */
public final class LayoutReliabilityTest extends DocumentEditorTest {
 String fixture(String name)throws Exception{try(InputStream in=getContext().getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8").trim();}}
 void startCase(String body,String mode)throws Exception{open("learning");input("数据化决策",body);h.js("__mode="+JSONObject.quote(mode)+";__attempts=[];__failedOnce=false;document.querySelector('#doc-more').click()");click("#doc-format");until("!document.querySelector('#doc-format').disabled");}
 void retry()throws Exception{click("#doc-format-retry");until("!document.querySelector('#doc-format').disabled");}
 boolean preview()throws Exception{return h.js("!!document.querySelector('#doc-preview')").equals("true");}
 @Override public void onStart(){Bundle out=new Bundle();try{
  h=new MainHost(this);h.open();model();String source=fixture("layout-decision.txt");
  h.js("window.__recorded="+fixture("layout-decision-overbold-plan.json")+";window.__layoutOriginal=LifeNative;window.__attempts=[];window.__mode='recorded';window.__failedOnce=false;LifeNative={call:(a,p,id)=>{const req=JSON.parse(p);if(a!=='ask'||req.tool?.name!=='plan_record_layout'){__layoutOriginal.call(a,p,id);return;}const data=JSON.parse(req.messages[1].content),us=data.units;__attempts.push(data.part);let result;if(__mode==='network'&&data.part===2&&!__failedOnce){__failedOnce=true;result={id,error:'无法连接模型服务，请检查网络和 API 地址'};}else{let plan;if(__mode==='recorded')plan=__recorded;else{const blocks=[];for(let i=0;i<us.length;i+=8)blocks.push({ids:us.slice(i,i+8).map(u=>u.id),style:'paragraph',emphasis:[]});plan={sections:[{heading:[],blocks}]};if(__mode==='decorations'){plan.sections[0].heading=['这是原文没有的标题'];plan.sections[0].blocks[0].style='unknown';plan.sections[0].blocks[0].emphasis=[{id:us[0].id,text:'这是不存在的加粗'}];}if(__mode==='missing')plan.sections[0].blocks.pop();}result={id,data:{text:JSON.stringify(plan),model:'synthetic-reliability'}};}setTimeout(()=>nativeReply(result),40);}};");
  startCase(source,"recorded");check(preview(),"Recorded formerly-rejected overbold reply now gives usable preview");check(h.js("__attempts.length===1").equals("true"),"Optional styling repaired on first attempt without more model calls");check(h.js("document.querySelectorAll('#doc-flow ol>li').length===5").equals("true"),"All five steps are complete list items");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(source)),"Preview does not mutate source");h.screenshot("layout-reliability-recorded.png");close();
  startCase(source,"decorations");check(preview()&&h.js("__attempts.length===1").equals("true"),"Invalid optional heading/style/emphasis corrected locally");check(h.js("!document.querySelector('#doc-flow').textContent.includes('这是原文没有的标题')").equals("true"),"Invented heading is not displayed");close();
  startCase(source,"missing");check(!preview()&&h.js("__attempts.length===2").equals("true"),"Omitted body still fails after one bounded repair retry");check(h.js("document.querySelector('#doc-status').textContent.includes('遗漏')&&!!document.querySelector('#doc-format-retry')").equals("true"),"Specific omission reason and manual retry stay visible");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(source)),"Hard failure leaves exact original intact");h.screenshot("layout-reliability-reason.png");close();
  StringBuilder longBody=new StringBuilder();for(int i=0;i<150;i++)longBody.append("这是第").append(i).append("项工作记录，需要保留所有时间顺序与条件。后续内容用来测试长笔记分段，不能遗漏任何内容。\n");String body=longBody.toString().trim();
  startCase(body,"network");int parts=Integer.parseInt(h.js("DocumentLayout.batches(DocumentLayout.units(DocumentRich.serialize(document.querySelector('#doc-body')))).length"));check(parts>=3,"Long note has multiple bounded batches");check(!preview()&&h.js("JSON.stringify(__attempts)").equals(JSONObject.quote("[1,2]")),"Network interruption stops at second batch without blind retry");check(h.js("document.querySelector('#doc-status').textContent.includes('无法连接模型服务')").equals("true"),"Native network cause is visible");retry();check(preview(),"Manual retry completes long note");check(h.js("__attempts.length==="+(parts+1)+"&&__attempts.filter(x=>x===1).length===1&&__attempts.filter(x=>x===2).length===2").equals("true"),"Retry reuses completed batch and requests only unfinished parts");click("#doc-cancel-format");h.js("__attempts=[];document.querySelector('#doc-more').click()");click("#doc-format");until("!document.querySelector('#doc-format').disabled");check(preview()&&h.js("__attempts.length==="+parts+"&&__attempts[0]===1").equals("true"),"Cancel preview clears session cache for deliberate fresh layout");close();
  for(String changed:new String[]{"title","body"}){startCase(body,"network");h.js(changed.equals("title")?"document.querySelector('#doc-title').value='新标题';document.querySelector('#doc-title').dispatchEvent(new Event('input'))":"document.querySelector('#doc-body').append('新补充的条件也必须保留。');document.querySelector('#doc-body').dispatchEvent(new Event('input'))");retry();check(preview()&&h.js("__attempts.filter(x=>x===1).length===2").equals("true"),"Changing "+changed+" invalidates previous batch cache");if(changed.equals("body"))check(h.js("document.querySelector('#doc-flow').textContent.includes('新补充的条件也必须保留')").equals("true"),"Newly added body is retained in recovered preview");close();}
  out.putString("stream","PASS LayoutReliabilityTest: "+passed+" checks; replay/synthetic only\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){try{h.screenshot("layout-reliability-failure.png");}catch(Exception ignored){}out.putString("stream","FAIL LayoutReliabilityTest after "+passed+": "+e+"\n");finish(Activity.RESULT_CANCELED,out);}}
}
